    // Scalar field size
    uint256 constant r    = 21888242871839275222246405745257275088548364400416034343698204186575808495617;
    // Base field size
    uint256 constant q   = 21888242871839275222246405745257275088696311157297823662689037894645226208583;

    // Verification Key data
    uint256 constant alphax  = 20491192805390485299153009773594534940189261866228447918068658471970481763042;
    uint256 constant alphay  = 9383485363053290200918347156157836566562967994039712273449902621266178545958;
    uint256 constant betax1  = 4252822878758300859123897981450591353533073413197771768651442665752259397132;
    uint256 constant betax2  = 6375614351688725206403948262868962793625744043794305715222011528459656738731;
    uint256 constant betay1  = 21847035105528745403288232691147584728191162732299865338377159692350059136679;
    uint256 constant betay2  = 10505242626370262277552901082094356697409835680220590971873171140371331206856;
    uint256 constant gammax1 = 11559732032986387107991004021392285783925812861821192530917403151452391805634;
    uint256 constant gammax2 = 10857046999023057135944570762232829481370756359578518086990519993285655852781;
    uint256 constant gammay1 = 4082367875863433681332203403145435568316851327593401208105741076214120093531;
    uint256 constant gammay2 = 8495653923123431417604973247489272438418190587263600148770280649306958101930;
    uint256 constant deltax1 = 3503463011162548405587789191138158584530149003263595775164879587564482208705;
    uint256 constant deltax2 = 12426206232075947590678157164399732690717230913675277424636845997120092486371;
    uint256 constant deltay1 = 19715252793777573883883972526991428845203450981716098231916183750063361995020;
    uint256 constant deltay2 = 13022244623092437397535210151570656384283808048908696033043503646353439962334;


    uint256 constant IC0x = 846260318224179708481134641402655656744183988870276402369233871321863276135;
    uint256 constant IC0y = 970315528404736895072284715430263604873605910858002153947502221207912449249;

    uint256 constant IC1x = 6139553577775695149677372307284029183043531217242269419309416393685787639310;
    uint256 constant IC1y = 7299409300841559269988144842671229154632654140707247750522673481012053577030;

    uint256 constant IC2x = 14091545171550687601144895604444312330754013243150165603927759448140713586225;
    uint256 constant IC2y = 924743251691650813016669452107713175810100382916654454821848792695469569717;

    uint256 constant IC3x = 21886441703274429015837191222118464482952656736696854820518890684563292611797;
    uint256 constant IC3y = 21768705525891851961054639195005301975681130373699621286291294672629704258580;

    uint256 constant IC4x = 5921608120283789998411516484871498383088571936963805330370063908415350225080;
    uint256 constant IC4y = 5606069493300704079722424717832096941116468713025551835649347891636119191124;

    uint256 constant IC5x = 12712940908561583469840796004138515867407930321863017282206964620622693721513;
    uint256 constant IC5y = 16707628303165898198119296820252349411985931953628527036739351458308465482793;

    uint256 constant IC6x = 9952768877356812672517457821985049438306657443758454259249829607592473757657;
    uint256 constant IC6y = 16576078685431359741614012862030583324969301287288053715842157492260956117077;


    // Memory data
    uint16 constant pVk = 0;
    uint16 constant pPairing = 128;

    uint16 constant pLastMem = 896;

    function verifyProof(uint[2] calldata _pA, uint[2][2] calldata _pB, uint[2] calldata _pC, uint[6] calldata _pubSignals) public view returns (bool) {
        assembly {
            function checkField(v) {
                if iszero(lt(v, r)) {
                    mstore(0, 0)
                    return(0, 0x20)
                }
            }

            // G1 function to multiply a G1 value(x,y) to value in an address
            function g1_mulAccC(pR, x, y, s) {
                let success
                let mIn := mload(0x40)
                mstore(mIn, x)
                mstore(add(mIn, 32), y)
                mstore(add(mIn, 64), s)

                success := staticcall(sub(gas(), 2000), 7, mIn, 96, mIn, 64)

                if iszero(success) {
                    mstore(0, 0)
                    return(0, 0x20)
                }

                mstore(add(mIn, 64), mload(pR))
                mstore(add(mIn, 96), mload(add(pR, 32)))

                success := staticcall(sub(gas(), 2000), 6, mIn, 128, pR, 64)

                if iszero(success) {
                    mstore(0, 0)
                    return(0, 0x20)
                }
            }

            function checkPairing(pA, pB, pC, pubSignals, pMem) -> isOk {
                let _pPairing := add(pMem, pPairing)
                let _pVk := add(pMem, pVk)

                mstore(_pVk, IC0x)
                mstore(add(_pVk, 32), IC0y)

                // Compute the linear combination vk_x

                g1_mulAccC(_pVk, IC1x, IC1y, calldataload(add(pubSignals, 0)))

                g1_mulAccC(_pVk, IC2x, IC2y, calldataload(add(pubSignals, 32)))

                g1_mulAccC(_pVk, IC3x, IC3y, calldataload(add(pubSignals, 64)))

                g1_mulAccC(_pVk, IC4x, IC4y, calldataload(add(pubSignals, 96)))

                g1_mulAccC(_pVk, IC5x, IC5y, calldataload(add(pubSignals, 128)))

                g1_mulAccC(_pVk, IC6x, IC6y, calldataload(add(pubSignals, 160)))


                // -A
                mstore(_pPairing, calldataload(pA))
                mstore(add(_pPairing, 32), mod(sub(q, calldataload(add(pA, 32))), q))

                // B
                mstore(add(_pPairing, 64), calldataload(pB))
                mstore(add(_pPairing, 96), calldataload(add(pB, 32)))
                mstore(add(_pPairing, 128), calldataload(add(pB, 64)))
                mstore(add(_pPairing, 160), calldataload(add(pB, 96)))

                // alpha1
                mstore(add(_pPairing, 192), alphax)
                mstore(add(_pPairing, 224), alphay)

                // beta2
                mstore(add(_pPairing, 256), betax1)
                mstore(add(_pPairing, 288), betax2)
                mstore(add(_pPairing, 320), betay1)
                mstore(add(_pPairing, 352), betay2)

                // vk_x
                mstore(add(_pPairing, 384), mload(add(pMem, pVk)))
                mstore(add(_pPairing, 416), mload(add(pMem, add(pVk, 32))))


                // gamma2
                mstore(add(_pPairing, 448), gammax1)
                mstore(add(_pPairing, 480), gammax2)
                mstore(add(_pPairing, 512), gammay1)
                mstore(add(_pPairing, 544), gammay2)

                // C
                mstore(add(_pPairing, 576), calldataload(pC))
                mstore(add(_pPairing, 608), calldataload(add(pC, 32)))

                // delta2
                mstore(add(_pPairing, 640), deltax1)
                mstore(add(_pPairing, 672), deltax2)
                mstore(add(_pPairing, 704), deltay1)
                mstore(add(_pPairing, 736), deltay2)


                let success := staticcall(sub(gas(), 2000), 8, _pPairing, 768, _pPairing, 0x20)

                isOk := and(success, mload(_pPairing))
            }

            let pMem := mload(0x40)
            mstore(0x40, add(pMem, pLastMem))

            // Validate that all evaluations ∈ F

            checkField(calldataload(add(_pubSignals, 0)))

            checkField(calldataload(add(_pubSignals, 32)))

            checkField(calldataload(add(_pubSignals, 64)))

            checkField(calldataload(add(_pubSignals, 96)))

            checkField(calldataload(add(_pubSignals, 128)))

            checkField(calldataload(add(_pubSignals, 160)))


            // Validate all evaluations
            let isValid := checkPairing(_pA, _pB, _pC, _pubSignals, pMem)

            mstore(0, isValid)
             return(0, 0x20)
         }
     }
 }

contracts/ProofVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title ProofVerifier
 * @dev Verifies zero-knowledge proofs on Ethereum
 * Deployed on Sepolia: 0x1e8150050a7a4715aad42b905c08df76883f396f
 */
contract ProofVerifier {
    // Mapping to track verified commitments
    mapping(bytes32 => bool) public verifiedProofs;

    // Mapping to store proof details
    mapping(string => ProofData) public proofDetails;

    struct ProofData {
        bytes32 commitment;
        uint8 proofType;
        address verifier;
        uint256 timestamp;
    }

    // Events
    event ProofVerified(
        string indexed proofId,
        bytes32 indexed commitment,
        address indexed verifier,
        uint8 proofType,
        uint256 timestamp
    );

    /**
     * @dev Verify a proof on-chain
     * @param proofId Unique identifier for the proof
     * @param commitment Cryptographic commitment (hash) of the proof
     * @param proofType Type of proof (0: KYC, 1: Location, 2: AI Content)
     */
    function verifyProof(
        string memory proofId,
        bytes32 commitment,
        uint8 proofType
    ) public {
        require(!verifiedProofs[commitment], "Proof already verified");
        require(proofType <= 2, "Invalid proof type");

        // Mark as verified
        verifiedProofs[commitment] = true;

        // Store proof details
        proofDetails[proofId] = ProofData({
            commitment: commitment,
            proofType: proofType,
            verifier: msg.sender,
            timestamp: block.timestamp
        });

        // Emit event
        emit ProofVerified(
            proofId,
            commitment,
            msg.sender,
            proofType,
            block.timestamp
        );
    }

    /**
     * @dev Check if a commitment has been verified
     * @param commitment The commitment to check
     * @return bool True if verified
     */
    function isVerified(bytes32 commitment) public view returns (bool) {
        return verifiedProofs[commitment];
    }

    /**
     * @dev Get proof details by ID
     * @param proofId The proof ID to query
     * @return ProofData The proof details
     */
    function getProofDetails(string memory proofId) public view returns (ProofData memory) {
        return proofDetails[proofId];
    }
}

